# Detection Script per Firefox
# Verifica se Firefox è installato sul sistema

$firefoxPaths = @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
)

$firefoxFound = $false

foreach ($path in $firefoxPaths) {
    try {
        $apps = Get-ItemProperty $path -ErrorAction SilentlyContinue | 
                Where-Object { $_.DisplayName -like "*Firefox*" }

        if ($apps) {
            $firefoxFound = $true
            Write-Host "Firefox rilevato: $($apps.DisplayName) - Versione: $($apps.DisplayVersion)"
            break
        }
    }
    catch {
        # Ignora errori di accesso al registro
    }
}

# Verifica anche la presenza dell'eseguibile
$firefoxExePaths = @(
    "${env:ProgramFiles}\Mozilla Firefox\firefox.exe",
    "${env:ProgramFiles(x86)}\Mozilla Firefox\firefox.exe"
)

foreach ($exePath in $firefoxExePaths) {
    if (Test-Path $exePath) {
        $firefoxFound = $true
        Write-Host "Firefox eseguibile trovato in: $exePath"
        break
    }
}

if ($firefoxFound) {
    Write-Host "Firefox installato - Remediation necessaria"
    exit 1  # Rilevato - necessita remediation
}
else {
    Write-Host "Firefox non installato - Nessuna azione necessaria"
    exit 0  # Non rilevato - compliant
}

# Remediation Script per Firefox
# Disinstalla Firefox dal sistema

$logPath = "$env:ProgramData\IntuneRemediation"
if (!(Test-Path $logPath)) {
    New-Item -ItemType Directory -Path $logPath -Force | Out-Null
}
$logFile = "$logPath\FirefoxUninstall_$(Get-Date -Format 'yyyyMMdd_HHmmss').log"

function Write-Log {
    param([string]$Message)
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    "$timestamp - $Message" | Out-File -FilePath $logFile -Append
    Write-Host $Message
}

Write-Log "=== Inizio disinstallazione Firefox ==="

# Chiudi eventuali processi Firefox in esecuzione
$processes = Get-Process -Name "firefox" -ErrorAction SilentlyContinue
if ($processes) {
    Write-Log "Chiusura processi Firefox in esecuzione..."
    $processes | Stop-Process -Force
    Start-Sleep -Seconds 2
}

# Array di percorsi del registro dove cercare Firefox
$uninstallPaths = @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
)

$uninstalled = $false

foreach ($path in $uninstallPaths) {
    try {
        $firefox = Get-ItemProperty $path -ErrorAction SilentlyContinue | 
                   Where-Object { $_.DisplayName -like "*Firefox*" }

        if ($firefox) {
            foreach ($app in $firefox) {
                $uninstallString = $app.UninstallString

                if ($uninstallString) {
                    Write-Log "Trovato: $($app.DisplayName) - Versione: $($app.DisplayVersion)"
                    Write-Log "Stringa disinstallazione: $uninstallString"

                    # Gestione diversi tipi di uninstaller
                    if ($uninstallString -like "*helper.exe*") {
                        # Uninstaller Mozilla standard
                        $uninstallString = $uninstallString -replace '"', ''
                        $arguments = "/S"  # Silent uninstall

                        Write-Log "Esecuzione disinstallazione silenziosa..."
                        $process = Start-Process -FilePath $uninstallString -ArgumentList $arguments -Wait -PassThru -NoNewWindow

                        if ($process.ExitCode -eq 0) {
                            Write-Log "Disinstallazione completata con successo"
                            $uninstalled = $true
                        }
                        else {
                            Write-Log "Disinstallazione terminata con codice: $($process.ExitCode)"
                            $uninstalled = $true
                        }
                    }
                    elseif ($uninstallString -like "msiexec*") {
                        # MSI installer
                        $productCode = $uninstallString -replace "msiexec.exe /[IX]", "" -replace "/I", "" -replace "{", "" -replace "}", "" -replace " ", ""
                        $arguments = "/X{$productCode} /qn /norestart"

                        Write-Log "Esecuzione disinstallazione MSI..."
                        $process = Start-Process -FilePath "msiexec.exe" -ArgumentList $arguments -Wait -PassThru -NoNewWindow

                        if ($process.ExitCode -eq 0 -or $process.ExitCode -eq 3010) {
                            Write-Log "Disinstallazione MSI completata"
                            $uninstalled = $true
                        }
                        else {
                            Write-Log "Disinstallazione MSI terminata con codice: $($process.ExitCode)"
                        }
                    }
                }
            }
        }
    }
    catch {
        Write-Log "Errore durante la disinstallazione: $_"
    }
}

# Pulizia cartelle residue
$firefoxFolders = @(
    "${env:ProgramFiles}\Mozilla Firefox",
    "${env:ProgramFiles(x86)}\Mozilla Firefox"
)

foreach ($folder in $firefoxFolders) {
    if (Test-Path $folder) {
        try {
            Write-Log "Rimozione cartella: $folder"
            Remove-Item -Path $folder -Recurse -Force -ErrorAction Stop
            Write-Log "Cartella rimossa con successo"
        }
        catch {
            Write-Log "Impossibile rimuovere la cartella $folder : $_"
        }
    }
}

if ($uninstalled) {
    Write-Log "=== Remediation completata con successo ==="
    exit 0
}
else {
    Write-Log "=== Nessuna installazione Firefox trovata o errore durante la disinstallazione ==="
    exit 1
}

