## Proactive Remediation per Errore 0x87d1fde8 - Lunghezza Minima Password

### Detection Script (64-bit only)

```powershell
<#
.SYNOPSIS
    Detection Script - Password Policy Cache Error 0x87d1fde8
.DESCRIPTION
    Rileva cache corrotta per impostazioni password policy su dispositivi 64-bit
.NOTES
    Esecuzione: System Context
    Architettura: 64-bit only
#>

# Verifica architettura - Exit se non 64-bit
if ([Environment]::Is64BitOperatingSystem -eq $false) {
    Write-Output "Sistema 32-bit - script non applicabile"
    Exit 0
}

try {
    $ErrorActionPreference = "Stop"

    # Percorso log
    $logPath = "$env:ProgramData\IntunePasswordPolicyRemediation"
    if (!(Test-Path $logPath)) { 
        New-Item -ItemType Directory -Path $logPath -Force | Out-Null 
    }

    $timestamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
    $detectionLog = "$logPath\Detection_$timestamp.log"

    function Write-Log {
        param($Message)
        $logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - $Message"
        $logMessage | Out-File $detectionLog -Append
        Write-Output $Message
    }

    Write-Log "=== INIZIO DETECTION - Sistema 64-bit ==="
    Write-Log "Computer: $env:COMPUTERNAME"

    $issuesFound = $false

    # 1. Verifica tipo join (Entra ID joined)
    Write-Log "Verifica tipo join dispositivo..."
    $dsregOutput = & dsregcmd /status
    $isEntraJoined = $dsregOutput | Select-String "AzureAdJoined\s*:\s*YES"

    if (!$isEntraJoined) {
        Write-Log "Dispositivo non Entra ID joined - policy non applicabile"
        Exit 0
    }
    Write-Log "Dispositivo Entra ID joined - OK"

    # 2. Verifica cache MDM per password policies
    Write-Log "Controllo cache MDM..."

    $mdmPolicyPaths = @(
        "HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\DeviceLock",
        "HKLM:\SOFTWARE\Microsoft\PolicyManager\Providers"
    )

    foreach ($path in $mdmPolicyPaths) {
        if (Test-Path $path) {
            $items = Get-ChildItem -Path $path -Recurse -ErrorAction SilentlyContinue | 
                Where-Object { 
                    $props = $_ | Get-ItemProperty -ErrorAction SilentlyContinue
                    $props.PSObject.Properties.Name -match "MinDevicePasswordLength|MinimumPasswordLength|DevicePasswordEnabled"
                }

            if ($items) {
                $issuesFound = $true
                Write-Log "PROBLEMA: Policy password residue trovate in MDM cache: $path"
                $items | ForEach-Object {
                    Write-Log "  - $($_.PSPath)"
                }
            }
        }
    }

    # 3. Verifica Intune Management Extension cache con errori specifici
    Write-Log "Controllo cache Intune Management Extension..."

    $imePaths = @(
        "HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\Policies",
        "HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\SideCarPolicies"
    )

    foreach ($cachePath in $imePaths) {
        if (Test-Path $cachePath) {
            Get-ChildItem -Path $cachePath -Recurse -ErrorAction SilentlyContinue | ForEach-Object {
                $props = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue

                # Cerca errore specifico 0x87d1fde8
                if ($props) {
                    $errorCode = $props.ErrorCode
                    $result = $props.Result

                    if ($errorCode -eq '0x87d1fde8' -or 
                        $errorCode -eq '-2016281112' -or 
                        $result -eq '-2016281112') {
                        $issuesFound = $true
                        Write-Log "PROBLEMA: Policy con errore 0x87d1fde8 trovata:"
                        Write-Log "  Path: $($_.PSPath)"
                        Write-Log "  ErrorCode: $errorCode"
                        Write-Log "  Result: $result"
                    }
                }
            }
        }
    }

    # 4. Verifica log eventi recenti (ultime 48 ore)
    Write-Log "Controllo Event Log DeviceManagement..."

    try {
        $events = Get-WinEvent -LogName "Microsoft-Windows-DeviceManagement-Enterprise-Diagnostics-Provider/Admin" -MaxEvents 100 -ErrorAction SilentlyContinue | 
            Where-Object { 
                $_.TimeCreated -gt (Get-Date).AddHours(-48) -and
                ($_.Message -match "0x87d1fde8|password.*length|MinDevicePasswordLength" -or
                 $_.Id -eq 404 -or $_.Id -eq 400)
            }

        if ($events) {
            $issuesFound = $true
            Write-Log "PROBLEMA: Eventi errore password policy trovati (ultimi 2 giorni): $($events.Count)"
            $events | Select-Object -First 3 | ForEach-Object {
                Write-Log "  - ID: $($_.Id) - Time: $($_.TimeCreated) - Message: $($_.Message.Substring(0, [Math]::Min(100, $_.Message.Length)))"
            }
        }
    } catch {
        Write-Log "Impossibile leggere Event Log (normale se non ci sono eventi)"
    }

    # 5. Verifica stato servizio Intune Management Extension
    Write-Log "Controllo servizio IntuneManagementExtension..."

    $imeService = Get-Service -Name "IntuneManagementExtension" -ErrorAction SilentlyContinue
    if ($imeService) {
        Write-Log "Servizio IME - Stato: $($imeService.Status)"
        if ($imeService.Status -ne 'Running') {
            $issuesFound = $true
            Write-Log "PROBLEMA: Servizio IME non in esecuzione"
        }
    } else {
        Write-Log "WARNING: Servizio IME non trovato"
    }

    # 6. Verifica ultima sincronizzazione Intune
    Write-Log "Controllo ultima sincronizzazione..."

    $enrollmentPath = Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Enrollments" -ErrorAction SilentlyContinue | 
        Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).UPN } | 
        Select-Object -First 1

    if ($enrollmentPath) {
        $props = Get-ItemProperty $enrollmentPath.PSPath
        $lastSync = $props.LastSuccessfulSyncTime
        if ($lastSync) {
            Write-Log "Ultima sincronizzazione: $lastSync"
        }
    }

    # Conclusione
    Write-Log "=== FINE DETECTION ==="

    if ($issuesFound) {
        Write-Log "RISULTATO: Problemi rilevati - REMEDIATION NECESSARIA"
        Write-Output "Cache policy corrotta rilevata - errore 0x87d1fde8 presente"
        Exit 1  # Trigger remediation
    } else {
        Write-Log "RISULTATO: Nessun problema rilevato - Sistema OK"
        Write-Output "Nessun problema rilevato"
        Exit 0  # No remediation needed
    }

} catch {
    $errorMsg = "ERRORE DETECTION: $($_.Exception.Message)"
    Write-Log $errorMsg
    Write-Error $errorMsg
    Exit 1
}
