        Write-Log "=== REMEDIATION COMPLETATA CON WARNING ==="
        Write-Log "==================================================================="
        Write-Log "Alcuni passaggi hanno generato warning - verificare i log"

        Write-Output "Remediation completata con warning - verificare log"
        Exit 0  # Exit 0 comunque perché la remediation è stata tentata
    }

} catch {
    $errorMsg = "ERRORE CRITICO REMEDIATION: $($_.Exception.Message)"
    Write-Log $errorMsg
    Write-Log "Stack Trace: $($_.Exception.StackTrace)"
    Write-Error $errorMsg
    Exit 1
}
