## Proactive Remediation - Rimozione Zoom (64-bit)

### Detection Script

```powershell
<#
.SYNOPSIS
    Detection Script - Zoom Client Installation (User-installed)
.DESCRIPTION
    Rileva installazioni Zoom (per-user e system-wide) su sistemi 64-bit
.NOTES
    Esecuzione: System Context
    Architettura: 64-bit only
    Autore: IT Admin
    Versione: 1.0
#>

# Verifica architettura - Exit se non 64-bit
if ([Environment]::Is64BitOperatingSystem -eq $false) {
    Write-Output "Sistema 32-bit - script non applicabile"
    Exit 0
}

try {
    $ErrorActionPreference = "Stop"

    # Percorso log
    $logPath = "$env:ProgramData\ZoomRemovalRemediation"
    if (!(Test-Path $logPath)) { 
        New-Item -ItemType Directory -Path $logPath -Force | Out-Null 
    }

    $timestamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
    $detectionLog = "$logPath\Detection_$timestamp.log"

    function Write-Log {
        param($Message)
        $logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - $Message"
        $logMessage | Out-File $detectionLog -Append -Encoding UTF8
        Write-Output $Message
    }

    Write-Log "=== INIZIO DETECTION ZOOM - Sistema 64-bit ==="
    Write-Log "Computer: $env:COMPUTERNAME"

    $zoomFound = $false
    $zoomLocations = @()

    # ===================================================================
    # 1. VERIFICA INSTALLAZIONI SYSTEM-WIDE (Program Files)
    # ===================================================================
    Write-Log "Controllo installazioni system-wide..."

    $systemPaths = @(
        "$env:ProgramFiles\Zoom\bin\Zoom.exe",
        "${env:ProgramFiles(x86)}\Zoom\bin\Zoom.exe",
        "$env:ProgramFiles\Zoom\uninstall\Installer.exe",
        "${env:ProgramFiles(x86)}\Zoom\uninstall\Installer.exe"
    )

    foreach ($path in $systemPaths) {
        if (Test-Path $path) {
            $zoomFound = $true
            $zoomLocations += $path
            Write-Log "  TROVATO: $path"

            # Ottieni versione se possibile
            try {
                $versionInfo = (Get-Item $path).VersionInfo
                Write-Log "    Versione: $($versionInfo.FileVersion)"
            } catch {
                Write-Log "    Versione: Non disponibile"
            }
        }
    }

    # ===================================================================
    # 2. VERIFICA INSTALLAZIONI PER-USER (AppData)
    # ===================================================================
    Write-Log "Controllo installazioni per-user..."

    # Ottieni tutti i profili utente
    $userProfiles = Get-ChildItem "C:\Users" -Directory -ErrorAction SilentlyContinue | 
        Where-Object { $_.Name -notmatch '^(Public|Default|All Users|Default User)$' }

    foreach ($profile in $userProfiles) {
        $userZoomPaths = @(
            "$($profile.FullName)\AppData\Roaming\Zoom\bin\Zoom.exe",
            "$($profile.FullName)\AppData\Roaming\Zoom\uninstall\Installer.exe"
        )

        foreach ($userPath in $userZoomPaths) {
            if (Test-Path $userPath) {
                $zoomFound = $true
                $zoomLocations += $userPath
                Write-Log "  TROVATO (User: $($profile.Name)): $userPath"

                try {
                    $versionInfo = (Get-Item $userPath).VersionInfo
                    Write-Log "    Versione: $($versionInfo.FileVersion)"
                } catch {
                    Write-Log "    Versione: Non disponibile"
                }
            }
        }
    }

    # ===================================================================
    # 3. VERIFICA REGISTRY (System e User Hives)
    # ===================================================================
    Write-Log "Controllo Registry..."

    # Registry system-wide (HKLM)
    $hklmPaths = @(
        "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )

    foreach ($regPath in $hklmPaths) {
        $apps = Get-ItemProperty $regPath -ErrorAction SilentlyContinue | 
            Where-Object { $_.DisplayName -like "*Zoom*" -and $_.Publisher -like "*Zoom*" }

        if ($apps) {
            foreach ($app in $apps) {
                $zoomFound = $true
                Write-Log "  TROVATO in Registry (HKLM): $($app.DisplayName) - Versione: $($app.DisplayVersion)"
                $zoomLocations += "Registry: $($app.PSPath)"
            }
        }
    }

    # Registry per-user (HKCU per ogni utente)
    foreach ($profile in $userProfiles) {
        $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
        $userRegPath = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"

        try {
            $userApps = Get-ItemProperty $userRegPath -ErrorAction SilentlyContinue | 
                Where-Object { $_.DisplayName -like "*Zoom*" }

            if ($userApps) {
                foreach ($app in $userApps) {
                    $zoomFound = $true
                    Write-Log "  TROVATO in Registry (User: $($profile.Name)): $($app.DisplayName)"
                    $zoomLocations += "Registry User: $($app.PSPath)"
                }
            }
        } catch {
            # Silently skip se non accessibile
        }
    }

    # ===================================================================
    # 4. VERIFICA PROCESSI IN ESECUZIONE
    # ===================================================================
    Write-Log "Controllo processi Zoom in esecuzione..."

    $zoomProcesses = Get-Process -Name "Zoom*" -ErrorAction SilentlyContinue
    if ($zoomProcesses) {
        Write-Log "  ATTENZIONE: Processi Zoom in esecuzione: $($zoomProcesses.Count)"
        foreach ($proc in $zoomProcesses) {
            Write-Log "    - $($proc.Name) (PID: $($proc.Id)) - Path: $($proc.Path)"
        }
    }

    # ===================================================================
    # 5. VERIFICA START MENU SHORTCUTS
    # ===================================================================
    Write-Log "Controllo collegamenti Start Menu..."

    $shortcutPaths = @(
        "$env:ProgramData\Microsoft\Windows\Start Menu\Programs",
        "$env:APPDATA\Microsoft\Windows\Start Menu\Programs"
    )

    foreach ($profile in $userProfiles) {
        $shortcutPaths += "$($profile.FullName)\AppData\Roaming\Microsoft\Windows\Start Menu\Programs"
    }

    foreach ($shortcutPath in $shortcutPaths) {
        if (Test-Path $shortcutPath) {
            $zoomShortcuts = Get-ChildItem -Path $shortcutPath -Recurse -Filter "*Zoom*.lnk" -ErrorAction SilentlyContinue
            if ($zoomShortcuts) {
                foreach ($shortcut in $zoomShortcuts) {
                    Write-Log "  TROVATO: Shortcut - $($shortcut.FullName)"
                    $zoomFound = $true
                }
            }
        }
    }

    # ===================================================================
    # CONCLUSIONE DETECTION
    # ===================================================================
    Write-Log ""
    Write-Log "=== FINE DETECTION ==="
    Write-Log "Totale posizioni Zoom trovate: $($zoomLocations.Count)"

    if ($zoomFound) {
        Write-Log "RISULTATO: Zoom rilevato - REMEDIATION NECESSARIA"
        Write-Output "Zoom installato rilevato - rimozione necessaria"
        Exit 1  # Trigger remediation
    } else {
        Write-Log "RISULTATO: Zoom NON rilevato - Sistema pulito"
        Write-Output "Zoom non rilevato"
        Exit 0  # No remediation needed
    }

} catch {
    $errorMsg = "ERRORE DETECTION: $($_.Exception.Message)"
    Write-Log $errorMsg
    Write-Error $errorMsg
    Exit 1
}
```

### Remediation Script

```powershell
<#
.SYNOPSIS
    Remediation Script - Rimozione Completa Zoom Client
.DESCRIPTION
    Rimuove tutte le installazioni Zoom (system-wide e per-user) in modalità silent
    Utilizza uninstaller nativi e pulizia manuale
.NOTES
    Esecuzione: System Context
    Architettura: 64-bit only
    Richiede riavvio: No
    Metodo: Uninstaller nativo + CleanZoom + Pulizia manuale
#>

# Verifica architettura - Exit se non 64-bit
if ([Environment]::Is64BitOperatingSystem -eq $false) {
    Write-Output "Sistema 32-bit - remediation non applicabile"
    Exit 0
}

try {
    $ErrorActionPreference = "Stop"

    # Percorso log
    $logPath = "$env:ProgramData\ZoomRemovalRemediation"
    if (!(Test-Path $logPath)) { 
        New-Item -ItemType Directory -Path $logPath -Force | Out-Null 
    }

    $timestamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
    $remediationLog = "$logPath\Remediation_$timestamp.log"

    function Write-Log {
        param($Message)
        $logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - $Message"
        $logMessage | Out-File $remediationLog -Append -Encoding UTF8
        Write-Output $Message
    }

    Write-Log "==================================================================="
    Write-Log "=== INIZIO REMEDIATION - RIMOZIONE ZOOM COMPLETA ================"
    Write-Log "==================================================================="
    Write-Log "Computer: $env:COMPUTERNAME"
    Write-Log "Sistema: 64-bit"

    $uninstallCount = 0
    $failedUninstalls = 0

    # ===================================================================
    # STEP 1: TERMINAZIONE PROCESSI ZOOM
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 1: Terminazione processi Zoom..."

    $zoomProcesses = @("Zoom", "ZoomWebinarHost", "ZoomNotes", "Outlook_Zoom_Plugin", "zTscoder", "airhost", "aomhost64", "CptHost", "CptInstall", "CptService", "RoomConnector", "ZComMsgr", "zCrashReport")

    foreach ($processName in $zoomProcesses) {
        $processes = Get-Process -Name $processName -ErrorAction SilentlyContinue
        if ($processes) {
            foreach ($proc in $processes) {
                try {
                    Stop-Process -Id $proc.Id -Force -ErrorAction Stop
                    Write-Log "  Processo terminato: $processName (PID: $($proc.Id))"
                } catch {
                    Write-Log "  WARNING: Impossibile terminare processo $processName (PID: $($proc.Id)): $_"
                }
            }
        }
    }

    Start-Sleep -Seconds 3
    Write-Log "Processi Zoom terminati"

    # ===================================================================
    # STEP 2: DOWNLOAD CleanZoom (Official Zoom Uninstaller)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 2: Download CleanZoom utility..."

    $cleanZoomPath = "$logPath\CleanZoom.exe"
    $cleanZoomUrl = "https://assets.zoom.us/docs/msi-templates/CleanZoom.zip"
    $cleanZoomZip = "$logPath\CleanZoom.zip"

    try {
        # Download CleanZoom
        Write-Log "  Download da: $cleanZoomUrl"
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $cleanZoomUrl -OutFile $cleanZoomZip -UseBasicParsing -ErrorAction Stop
        Write-Log "  Download completato: CleanZoom.zip"

        # Estrai CleanZoom.exe
        Expand-Archive -Path $cleanZoomZip -DestinationPath $logPath -Force -ErrorAction Stop
        Write-Log "  Estratto: CleanZoom.exe"

        # Cleanup zip
        Remove-Item $cleanZoomZip -Force -ErrorAction SilentlyContinue

    } catch {
        Write-Log "  WARNING: Download CleanZoom fallito: $_"
        Write-Log "  Procederò con metodo alternativo..."
    }

    # ===================================================================
    # STEP 3: UNINSTALL SYSTEM-WIDE (HKLM)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 3: Disinstallazione system-wide..."

    $hklmPaths = @(
        "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )

    foreach ($regPath in $hklmPaths) {
        $apps = Get-ItemProperty $regPath -ErrorAction SilentlyContinue | 
            Where-Object { $_.DisplayName -like "*Zoom*" -and $_.Publisher -like "*Zoom*" }

        foreach ($app in $apps) {
            Write-Log "  Trovato: $($app.DisplayName) - Versione: $($app.DisplayVersion)"

            $uninstallString = $app.UninstallString
            $quietUninstallString = $app.QuietUninstallString

            if ($quietUninstallString) {
                Write-Log "    Esecuzione: $quietUninstallString"
                try {
                    Start-Process -FilePath "cmd.exe" -ArgumentList "/c $quietUninstallString" -Wait -NoNewWindow -ErrorAction Stop
                    Write-Log "    Disinstallazione completata (quiet)"
                    $uninstallCount++
                } catch {
                    Write-Log "    ERRORE quiet uninstall: $_"
                    $failedUninstalls++
                }
            } elseif ($uninstallString) {
                # Aggiungi parametri silent
                if ($uninstallString -match "msiexec") {
                    $silentUninstall = $uninstallString -replace "/I", "/X"
                    $silentUninstall += " /quiet /norestart"
                } else {
                    $silentUninstall = "$uninstallString /silent"
                }

                Write-Log "    Esecuzione: $silentUninstall"
                try {
                    Start-Process -FilePath "cmd.exe" -ArgumentList "/c $silentUninstall" -Wait -NoNewWindow -ErrorAction Stop
                    Write-Log "    Disinstallazione completata"
                    $uninstallCount++
                } catch {
                    Write-Log "    ERRORE uninstall: $_"
                    $failedUninstalls++
                }
            }
        }
    }

    # ===================================================================
    # STEP 4: UNINSTALL PER-USER (HKCU)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 4: Disinstallazione per-user..."

    # Ottieni tutti i profili utente
    $userProfiles = Get-ChildItem "C:\Users" -Directory -ErrorAction SilentlyContinue | 
        Where-Object { $_.Name -notmatch '^(Public|Default|All Users|Default User)$' }

    foreach ($profile in $userProfiles) {
        Write-Log "  Controllo profilo: $($profile.Name)"

        # Trova uninstaller per-user
        $userUninstallerPaths = @(
            "$($profile.FullName)\AppData\Roaming\Zoom\uninstall\Installer.exe"
        )

        foreach ($uninstallerPath in $userUninstallerPaths) {
            if (Test-Path $uninstallerPath) {
                Write-Log "    Trovato uninstaller: $uninstallerPath"
                try {
                    Start-Process -FilePath $uninstallerPath -ArgumentList "/uninstall /silent" -Wait -NoNewWindow -ErrorAction Stop
                    Write-Log "    Disinstallazione completata per: $($profile.Name)"
                    $uninstallCount++
                } catch {
                    Write-Log "    WARNING: Disinstallazione fallita: $_"
                    $failedUninstalls++
                }
            }
        }

        # Verifica e rimuovi anche da Registry user hive
        try {
            $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
            $userRegPath = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"

            $userApps = Get-ItemProperty $userRegPath -ErrorAction SilentlyContinue | 
                Where-Object { $_.DisplayName -like "*Zoom*" }

            foreach ($userApp in $userApps) {
                Write-Log "    Registry entry: $($userApp.DisplayName)"
                # Uninstall già eseguito sopra, qui solo log
            }
        } catch {
            # Skip se non accessibile
        }
    }

    # ===================================================================
    # STEP 5: ESECUZIONE CleanZoom (se disponibile)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 5: Esecuzione CleanZoom utility..."

    if (Test-Path $cleanZoomPath) {
        try {
            Write-Log "  Esecuzione: CleanZoom.exe /silent"
            Start-Process -FilePath $cleanZoomPath -ArgumentList "/silent" -Wait -NoNewWindow -ErrorAction Stop
            Write-Log "  CleanZoom completato con successo"
            $uninstallCount++
        } catch {
            Write-Log "  WARNING: CleanZoom fallito: $_"
        }
    } else {
        Write-Log "  CleanZoom non disponibile - skip"
    }

    # ===================================================================
    # STEP 6: PULIZIA MANUALE FILE E CARTELLE RESIDUE
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 6: Pulizia file e cartelle residue..."

    # Cartelle system-wide
    $systemFolders = @(
        "$env:ProgramFiles\Zoom",
        "${env:ProgramFiles(x86)}\Zoom",
        "$env:ProgramData\Zoom"
    )

    foreach ($folder in $systemFolders) {
        if (Test-Path $folder) {
            try {
                Remove-Item -Path $folder -Recurse -Force -ErrorAction Stop
                Write-Log "  Rimossa: $folder"
            } catch {
                Write-Log "  WARNING: Impossibile rimuovere $folder : $_"
            }
        }
    }

    # Cartelle per-user
    foreach ($profile in $userProfiles) {
        $userZoomFolders = @(
            "$($profile.FullName)\AppData\Roaming\Zoom",
            "$($profile.FullName)\AppData\Local\Zoom",
            "$($profile.FullName)\Documents\Zoom"
        )

        foreach ($userFolder in $userZoomFolders) {
            if (Test-Path $userFolder) {
                try {
                    Remove-Item -Path $userFolder -Recurse -Force -ErrorAction Stop
                    Write-Log "  Rimossa (User $($profile.Name)): $userFolder"
                } catch {
                    Write-Log "  WARNING: Impossibile rimuovere $userFolder : $_"
                }
            }
        }
    }

    # ===================================================================
    # STEP 7: PULIZIA REGISTRY RESIDUO
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 7: Pulizia registry residuo..."

    $registryPaths = @(
        "HKLM:\Software\Zoom",
        "HKLM:\Software\WOW6432Node\Zoom",
        "HKLM:\Software\Classes\ZoomLauncher"
    )

    foreach ($regPath in $registryPaths) {
        if (Test-Path $regPath) {
            try {
                Remove-Item -Path $regPath -Recurse -Force -ErrorAction Stop
                Write-Log "  Rimossa chiave: $regPath"
            } catch {
                Write-Log "  WARNING: Impossibile rimuovere $regPath : $_"
            }
        }
    }

    # Pulizia per user registry
    foreach ($profile in $userProfiles) {
        try {
            $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
            $userRegPaths = @(
                "Registry::HKEY_USERS\$sid\Software\Zoom",
                "Registry::HKEY_USERS\$sid\Software\Classes\ZoomLauncher"
            )

            foreach ($userRegPath in $userRegPaths) {
                if (Test-Path $userRegPath) {
                    Remove-Item -Path $userRegPath -Recurse -Force -ErrorAction SilentlyContinue
                    Write-Log "  Rimossa chiave user ($($ profile.Name)): $userRegPath"
                }
            }
        } catch {
            # Skip se non accessibile
        }
    }

    # ===================================================================
    # STEP 8: RIMOZIONE SHORTCUTS
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 8: Rimozione collegamenti..."

    $shortcutLocations = @(
        "$env:ProgramData\Microsoft\Windows\Start Menu\Programs",
        "$env:Public\Desktop"
    )

    foreach ($profile in $userProfiles) {
        $shortcutLocations += "$($profile.FullName)\AppData\Roaming\Microsoft\Windows\Start Menu\Programs"
        $shortcutLocations += "$($profile.FullName)\Desktop"
    }

    foreach ($location in $shortcutLocations) {
        if (Test-Path $location) {
            $shortcuts = Get-ChildItem -Path $location -Recurse -Filter "*Zoom*.lnk" -ErrorAction SilentlyContinue
            foreach ($shortcut in $shortcuts) {
                try {
                    Remove-Item -Path $shortcut.FullName -Force -ErrorAction Stop
                    Write-Log "  Rimosso: $($shortcut.FullName)"
                } catch {
                    Write-Log "  WARNING: Impossibile rimuovere $($shortcut.FullName) : $_"
                }
            }
        }
    }

    # ===================================================================
    # STEP 9: PULIZIA TASK SCHEDULER
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 9: Pulizia Scheduled Tasks..."

    $zoomTasks = Get-ScheduledTask | Where-Object { $_.TaskName -like "*Zoom*" }
    foreach ($task in $zoomTasks) {
        try {
            Unregister-ScheduledTask -TaskName $task.TaskName -TaskPath $task.TaskPath -Confirm:$false -ErrorAction Stop
            Write-Log "  Task rimosso: $($task.TaskName)"
        } catch {
            Write-Log "  WARNING: Impossibile rimuovere task $($task.TaskName) : $_"
        }
    }

    # ===================================================================
    # STEP 10: CLEANUP TEMPORANEO
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 10: Pulizia file temporanei..."

    if (Test-Path $cleanZoomPath) {
        Remove-Item -Path $cleanZoomPath -Force -ErrorAction SilentlyContinue
        Write-Log "  Rimosso: CleanZoom.exe"
    }

    # ===================================================================
    # STEP 11: VERIFICA POST-REMEDIATION
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 11: Verifica post-remediation..."

    $stillInstalled = $false

    # Check residui
    $checkPaths = @(
        "$env:ProgramFiles\Zoom\bin\Zoom.exe",
        "${env:ProgramFiles(x86)}\Zoom\bin\Zoom.exe"
    )

    foreach ($checkPath in $checkPaths) {
        if (Test-Path $checkPath) {
            $stillInstalled = $true
            Write-Log "  WARNING: File ancora presente: $checkPath"
        }
    }

    # Check processi
    $runningZoom = Get-Process -Name "Zoom*" -ErrorAction SilentlyContinue
    if ($runningZoom) {
        Write-Log "  WARNING: Processi Zoom ancora in esecuzione: $($runningZoom.Count)"
        $stillInstalled = $true
    }

    # ===================================================================
    # CONCLUSIONE
    # ===================================================================
    Write-Log ""
    Write-Log "==================================================================="

    if (!$stillInstalled) {
        Write-Log "=== REMEDIATION COMPLETATA CON SUCCESSO ==="
        Write-Log "==================================================================="
        Write-Log ""
        Write-Log "RIEPILOGO:"
        Write-Log "  - Disinstallazioni eseguite: $uninstallCount"
        Write-Log "  - Disinstallazioni fallite: $failedUninstalls"
        Write-Log "  - Zoom completamente rimosso dal sistema"
        Write-Log ""
        Write-Log "Log completo disponibile in: $remediationLog"

        Write-Output "Zoom rimosso con successo"
        Exit 0
    } else {
        Write-Log "=== REMEDIATION COMPLETATA CON WARNING ==="
        Write-Log "==================================================================="
        Write-Log ""
        Write-Log "RIEPILOGO:"
        Write-Log "  - Disinstallazioni eseguite: $uninstallCount"
        Write-Log "  - Disinstallazioni fallite: $failedUninstalls"
        Write-Log "  - WARNING: Alcuni componenti Zoom potrebbero essere ancora presenti"
        Write-Log ""
        Write-Log "Consigliato: Riavviare il dispositivo e rieseguire lo script"

        Write-Output "Zoom parzialmente rimosso - verificare log"
        Exit 0  # Exit 0 comunque per non bloccare Intune
    }

} catch {
    $errorMsg = "ERRORE CRITICO REMEDIATION: $($_.Exception.Message)"
    Write-Log $errorMsg
    Write-Log "Stack Trace: $($_.Exception.StackTrace)"
    Write-Error $errorMsg
    Exit 1
}
