        $logSize = (Get-Item $detectionLog).Length / 1MB
        if ($logSize -gt 5) {
            $archivePath = "$logPath\Archive"
            if (!(Test-Path $archivePath)) { 
                New-Item -ItemType Directory -Path $archivePath -Force | Out-Null 
            }
            $archiveName = "Detection_$(Get-Date -Format 'yyyyMMdd_HHmmss').log"
            Move-Item $detectionLog "$archivePath\$archiveName" -Force -ErrorAction SilentlyContinue
        }
    }

    # Pulizia log vecchi (>30 giorni)
    if (Test-Path "$logPath\Archive") {
        Get-ChildItem "$logPath\Archive" -Filter "*.log" | 
            Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-30) } | 
            Remove-Item -Force -ErrorAction SilentlyContinue
    }

    function Write-Log {
        param($Message)
        $logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - $Message"
        $logMessage | Out-File $detectionLog -Append -Encoding UTF8
        # Rimuovi Write-Output duplicato da funzione
    }

    Write-Log "=== INIZIO DETECTION ZOOM - Sistema 64-bit ==="
    Write-Log "Computer: $env:COMPUTERNAME"
    Write-Log "User Context: SYSTEM"

    $zoomFound = $false
    $zoomLocations = @()

    # ===================================================================
    # 1. VERIFICA INSTALLAZIONI SYSTEM-WIDE (Program Files)
    # ===================================================================
    Write-Log "Controllo installazioni system-wide..."

    $systemPaths = @(
        "$env:ProgramFiles\Zoom\bin\Zoom.exe",
        "${env:ProgramFiles(x86)}\Zoom\bin\Zoom.exe",
        "$env:ProgramFiles\Zoom\uninstall\Installer.exe",
        "${env:ProgramFiles(x86)}\Zoom\uninstall\Installer.exe"
    )

    foreach ($path in $systemPaths) {
        if (Test-Path $path) {
            $zoomFound = $true
            $zoomLocations += $path
            Write-Log "  TROVATO: $path"

            # Ottieni versione se possibile
            try {
                $versionInfo = (Get-Item $path).VersionInfo
                Write-Log "    Versione: $($versionInfo.FileVersion)"
                Write-Log "    Product: $($versionInfo.ProductName)"
            } catch {
                Write-Log "    Versione: Non disponibile"
            }
        }
    }

    # ===================================================================
    # 2. VERIFICA INSTALLAZIONI PER-USER (AppData)
    # ===================================================================
    Write-Log "Controllo installazioni per-user..."

    # Ottieni tutti i profili utente
    $userProfiles = Get-ChildItem "C:\Users" -Directory -ErrorAction SilentlyContinue | 
        Where-Object { $_.Name -notmatch '^(Public|Default|All Users|Default User|TEMP)$' }

    Write-Log "  Profili utente trovati: $($userProfiles.Count)"

    foreach ($profile in $userProfiles) {
        Write-Log "  Scansione profilo: $($profile.Name)"

        $userZoomPaths = @(
            "$($profile.FullName)\AppData\Roaming\Zoom\bin\Zoom.exe",
            "$($profile.FullName)\AppData\Roaming\Zoom\uninstall\Installer.exe",
            "$($profile.FullName)\AppData\Local\Zoom\bin\Zoom.exe"  # Fix: aggiungi anche Local
        )

        foreach ($userPath in $userZoomPaths) {
            if (Test-Path $userPath) {
                $zoomFound = $true
                $zoomLocations += $userPath
                Write-Log "    TROVATO: $userPath"

                try {
                    $versionInfo = (Get-Item $userPath).VersionInfo
                    Write-Log "      Versione: $($versionInfo.FileVersion)"
                } catch {
                    Write-Log "      Versione: Non disponibile"
                }
            }
        }
    }

    # ===================================================================
    # 3. VERIFICA REGISTRY (System e User Hives)
    # ===================================================================
    Write-Log "Controllo Registry..."

    # Registry system-wide (HKLM)
    $hklmPaths = @(
        "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )

    foreach ($regPath in $hklmPaths) {
        $apps = Get-ItemProperty $regPath -ErrorAction SilentlyContinue | 
            Where-Object { 
                ($_.DisplayName -like "*Zoom*") -and 
                (($_.Publisher -like "*Zoom*") -or [string]::IsNullOrEmpty($_.Publisher))
            }

        if ($apps) {
            foreach ($app in $apps) {
                $zoomFound = $true
                Write-Log "  TROVATO in Registry (HKLM): $($app.DisplayName) - Versione: $($app.DisplayVersion)"
                $zoomLocations += "Registry: $($app.PSPath)"
            }
        }
    }

    # Registry per-user (HKEY_USERS)
    foreach ($profile in $userProfiles) {
        # FIX: Gestione robusta traduzione SID
        $sid = $null

        try {
            # Tentativo 1: Nome semplice (utenti locali)
            $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
        } catch {
            # Tentativo 2: COMPUTERNAME\username
            try {
                $sid = (New-Object System.Security.Principal.NTAccount("$env:COMPUTERNAME\$($profile.Name)")).Translate([System.Security.Principal.SecurityIdentifier]).Value
            } catch {
                # Tentativo 3: Cerca SID direttamente da profilo
                try {
                    $profileListPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\*"
                    $profileReg = Get-ItemProperty $profileListPath -ErrorAction SilentlyContinue | 
                        Where-Object { $_.ProfileImagePath -eq $profile.FullName }

                    if ($profileReg) {
                        $sid = $profileReg.PSChildName
                    }
                } catch {
                    Write-Log "    WARNING: Impossibile ottenere SID per $($profile.Name) - Skip (probabile Azure AD o profilo orfano)"
                    continue
                }
            }
        }

        if ($sid) {
            $userRegPath = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"

            try {
                $userApps = Get-ItemProperty $userRegPath -ErrorAction SilentlyContinue | 
                    Where-Object { $_.DisplayName -like "*Zoom*" }

                if ($userApps) {
                    foreach ($app in $userApps) {
                        $zoomFound = $true
                        Write-Log "    TROVATO in Registry user: $($app.DisplayName) - Ver: $($app.DisplayVersion)"
                        $zoomLocations += "Registry User ($($profile.Name)): $($app.PSPath)"
                    }
                }
            } catch {
                Write-Log "    WARNING: Errore lettura registry per SID $sid : $_"
            }
        }
    }

    # ===================================================================
    # 4. VERIFICA PROCESSI IN ESECUZIONE
    # ===================================================================
    Write-Log "Controllo processi Zoom in esecuzione..."

    $zoomProcesses = Get-Process -Name "Zoom*" -ErrorAction SilentlyContinue
    if ($zoomProcesses) {
        $zoomFound = $true  # Fix: imposta flag se processi trovati
        Write-Log "  ATTENZIONE: Processi Zoom in esecuzione: $($zoomProcesses.Count)"
        foreach ($proc in $zoomProcesses) {
            Write-Log "    - $($proc.Name) (PID: $($proc.Id)) - Path: $($proc.Path)"
        }
    } else {
        Write-Log "  Nessun processo Zoom in esecuzione"
    }

    # ===================================================================
    # 5. VERIFICA START MENU SHORTCUTS
    # ===================================================================
    Write-Log "Controllo collegamenti Start Menu..."

    # FIX: Rimuovi $env:APPDATA che in System Context non serve
    $shortcutPaths = @(
        "$env:ProgramData\Microsoft\Windows\Start Menu\Programs"
    )

    foreach ($profile in $userProfiles) {
        $shortcutPaths += "$($profile.FullName)\AppData\Roaming\Microsoft\Windows\Start Menu\Programs"
        $shortcutPaths += "$($profile.FullName)\Desktop"  # Aggiungi anche Desktop
    }

    $shortcutsFound = 0
    foreach ($shortcutPath in $shortcutPaths) {
        if (Test-Path $shortcutPath) {
            $zoomShortcuts = Get-ChildItem -Path $shortcutPath -Recurse -Filter "*Zoom*.lnk" -ErrorAction SilentlyContinue
            if ($zoomShortcuts) {
                foreach ($shortcut in $zoomShortcuts) {
                    Write-Log "  TROVATO: Shortcut - $($shortcut.FullName)"
                    $zoomFound = $true
                    $shortcutsFound++
                }
            }
        }
    }

    if ($shortcutsFound -eq 0) {
        Write-Log "  Nessun collegamento Zoom trovato"
    }

    # ===================================================================
    # CONCLUSIONE DETECTION
    # ===================================================================
    Write-Log ""
    Write-Log "=== FINE DETECTION ==="
    Write-Log "Totale posizioni Zoom trovate: $($zoomLocations.Count)"

    if ($zoomFound) {
        Write-Log "RISULTATO: Zoom rilevato - REMEDIATION NECESSARIA"
        Write-Output "Zoom installato rilevato - rimozione necessaria"
        Exit 1  # Trigger remediation
    } else {
        Write-Log "RISULTATO: Zoom NON rilevato - Sistema pulito"
        Write-Output "Zoom non rilevato"
        Exit 0  # No remediation needed
    }

} catch {
    $errorMsg = "ERRORE CRITICO DETECTION: $($_.Exception.Message)"
    Write-Log $errorMsg
    Write-Log "Stack trace: $($_.Exception.StackTrace)"

    # FIX: Exit 0 invece di 1 per evitare remediation su errore script
    Write-Output "Errore detection - verificare log: $detectionLog"
    Exit 0  # Non trigger remediation su errore script
}
```

## 📊 Riepilogo Modifiche

| Issue | Originale | Corretto | Priorità |
|-------|-----------|----------|----------|
| **Traduzione SID** | ❌ Fallisce su Azure AD | ✅ 3 tentativi + fallback | 🔴 Alta |
| **Accumulo log** | ❌ 1 file/esecuzione | ✅ Rotazione + pulizia | 🟡 Media |
| **Publisher filter** | ⚠️ Troppo restrittivo | ✅ Gestisce Publisher vuoto | 🟡 Media |
| **$env:APPDATA in shortcuts** | ❌ Path inutile | ✅ Rimosso | 🟡 Media |
| **Processo detection** | ⚠️ Non imposta $zoomFound | ✅ Flag impostato | 🟢 Bassa |
| **Exit su errore** | ⚠️ Exit 1 trigger remediation | ✅ Exit 0 con warning | 🟢 Bassa |
| **AppData\Local** | ❌ Non controllato | ✅ Aggiunto | 🟢 Bassa |
| **Desktop shortcuts** | ❌ Non controllato | ✅ Aggiunto | 🟢 Bassa |

