    $foldersRemoved = 0
    $foldersSkipped = 0

    # Cartelle system-wide
    $systemFolders = @(
        "$env:ProgramFiles\Zoom",
        "${env:ProgramFiles(x86)}\Zoom",
        "$env:ProgramData\Zoom",
        "$env:ProgramData\ZoomInstaller"  # Aggiungi cartella installer
    )

    foreach ($folder in $systemFolders) {
        if (Test-Path $folder) {
            Write-Log "  Tentativo rimozione: $folder"
            try {
                # Prima prova rimozione ricorsiva
                Remove-Item -Path $folder -Recurse -Force -ErrorAction Stop
                Write-Log "    OK - Cartella rimossa"
                $foldersRemoved++
            } catch {
                Write-Log "    WARNING: $_"

                # Tentativo alternativo: forza unlock dei file
                try {
                    Get-ChildItem -Path $folder -Recurse -Force | 
                        ForEach-Object { 
                            $_.Attributes = 'Normal'
                            Remove-Item $_.FullName -Force -ErrorAction SilentlyContinue 
                        }
                    Remove-Item -Path $folder -Recurse -Force -ErrorAction Stop
                    Write-Log "    OK - Cartella rimossa (secondo tentativo)"
                    $foldersRemoved++
                } catch {
                    Write-Log "    ERRORE: Impossibile rimuovere completamente"
                    $foldersSkipped++
                    $cleanupErrors += "Folder: $folder"
                }
            }
        }
    }

    # Cartelle per-user
    foreach ($profile in $userProfiles) {
        $userZoomFolders = @(
            "$($profile.FullName)\AppData\Roaming\Zoom",
            "$($profile.FullName)\AppData\Local\Zoom",
            "$($profile.FullName)\Documents\Zoom"
        )

        foreach ($userFolder in $userZoomFolders) {
            if (Test-Path $userFolder) {
                Write-Log "  Tentativo rimozione (User: $($profile.Name)): $userFolder"
                try {
                    Remove-Item -Path $userFolder -Recurse -Force -ErrorAction Stop
                    Write-Log "    OK - Cartella rimossa"
                    $foldersRemoved++
                } catch {
                    Write-Log "    WARNING: $_"
                    $foldersSkipped++
                    $cleanupErrors += "User folder ($($profile.Name)): $userFolder"
                }
            }
        }
    }

    Write-Log "  Cartelle rimosse: $foldersRemoved"
    if ($foldersSkipped -gt 0) {
        Write-Log "  Cartelle con errori: $foldersSkipped"
    }

    # ===================================================================
    # STEP 7: PULIZIA REGISTRY RESIDUO
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 7: Pulizia registry residuo..."

    $regKeysRemoved = 0
    $regKeysSkipped = 0

    # Registry system-wide
    $registryPaths = @(
        "HKLM:\Software\Zoom",
        "HKLM:\Software\WOW6432Node\Zoom",
        "HKLM:\Software\Classes\ZoomLauncher",
        "HKLM:\Software\Classes\.zoom",
        "HKLM:\Software\Classes\zoom"
    )

    foreach ($regPath in $registryPaths) {
        if (Test-Path $regPath) {
            Write-Log "  Tentativo rimozione: $regPath"
            try {
                Remove-Item -Path $regPath -Recurse -Force -ErrorAction Stop
                Write-Log "    OK - Chiave rimossa"
                $regKeysRemoved++
            } catch {
                Write-Log "    WARNING: $_"
                $regKeysSkipped++
                $cleanupErrors += "Registry: $regPath"
            }
        }
    }

    # Registry per-user
    foreach ($profile in $userProfiles) {
        # Ottieni SID (usa stessa logica robusta)
        $sid = $null
        try {
            $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
        } catch {
            try {
                $sid = (New-Object System.Security.Principal.NTAccount("$env:COMPUTERNAME\$($profile.Name)")).Translate([System.Security.Principal.SecurityIdentifier]).Value
            } catch {
                continue  # Skip se SID non ottenibile
            }
        }

        if ($sid) {
            $userRegPaths = @(
                "Registry::HKEY_USERS\$sid\Software\Zoom",
                "Registry::HKEY_USERS\$sid\Software\Classes\ZoomLauncher"
            )

            foreach ($userRegPath in $userRegPaths) {
                if (Test-Path $userRegPath) {
                    Write-Log "  Tentativo rimozione (User: $($profile.Name)): $userRegPath"
                    try {
                        Remove-Item -Path $userRegPath -Recurse -Force -ErrorAction Stop
                        Write-Log "    OK - Chiave user rimossa"
                        $regKeysRemoved++
                    } catch {
                        Write-Log "    WARNING: $_"
                        $regKeysSkipped++
                    }
                }
            }
        }
    }

    Write-Log "  Chiavi registry rimosse: $regKeysRemoved"
    if ($regKeysSkipped -gt 0) {
        Write-Log "  Chiavi con errori: $regKeysSkipped"
    }

    # ===================================================================
    # STEP 8: RIMOZIONE SHORTCUTS
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 8: Rimozione collegamenti..."

    $shortcutsRemoved = 0

    $shortcutLocations = @(
        "$env:ProgramData\Microsoft\Windows\Start Menu\Programs",
        "$env:Public\Desktop"
    )

    foreach ($profile in $userProfiles) {
        $shortcutLocations += "$($profile.FullName)\AppData\Roaming\Microsoft\Windows\Start Menu\Programs"
        $shortcutLocations += "$($profile.FullName)\Desktop"
    }

    foreach ($location in $shortcutLocations) {
        if (Test-Path $location) {
            $shortcuts = Get-ChildItem -Path $location -Recurse -Filter "*Zoom*.lnk" -ErrorAction SilentlyContinue
            foreach ($shortcut in $shortcuts) {
                Write-Log "  Tentativo rimozione: $($shortcut.FullName)"
                try {
                    Remove-Item -Path $shortcut.FullName -Force -ErrorAction Stop
                    Write-Log "    OK - Collegamento rimosso"
                    $shortcutsRemoved++
                } catch {
                    Write-Log "    WARNING: $_"
                }
            }
        }
    }

    if ($shortcutsRemoved -eq 0) {
        Write-Log "  Nessun collegamento trovato"
    } else {
        Write-Log "  Collegamenti rimossi: $shortcutsRemoved"
    }

    # ===================================================================
    # STEP 9: PULIZIA TASK SCHEDULER
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 9: Pulizia Scheduled Tasks..."

    $tasksRemoved = 0

    $zoomTasks = Get-ScheduledTask -ErrorAction SilentlyContinue | 
        Where-Object { $_.TaskName -like "*Zoom*" }

    if ($zoomTasks) {
        foreach ($task in $zoomTasks) {
            Write-Log "  Tentativo rimozione: $($task.TaskName) (Path: $($task.TaskPath))"
            try {
                Unregister-ScheduledTask -TaskName $task.TaskName -TaskPath $task.TaskPath -Confirm:$false -ErrorAction Stop
                Write-Log "    OK - Task rimosso"
                $tasksRemoved++
            } catch {
                Write-Log "    WARNING: $_"
            }
        }
    } else {
        Write-Log "  Nessun Scheduled Task Zoom trovato"
    }

    # ===================================================================
    # STEP 10: PULIZIA SERVIZI (se esistenti)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 10: Pulizia servizi Zoom..."

    $servicesRemoved = 0
    $zoomServices = Get-Service -Name "*Zoom*" -ErrorAction SilentlyContinue

    if ($zoomServices) {
        foreach ($service in $zoomServices) {
            Write-Log "  Trovato servizio: $($service.Name) - Status: $($service.Status)"
            try {
                # Stop servizio se running
                if ($service.Status -eq 'Running') {
                    Stop-Service -Name $service.Name -Force -ErrorAction Stop
                    Write-Log "    Servizio arrestato"
                }

                # Rimuovi servizio
                sc.exe delete $service.Name | Out-Null
                Write-Log "    OK - Servizio rimosso"
                $servicesRemoved++
            } catch {
                Write-Log "    WARNING: $_"
            }
        }
    } else {
        Write-Log "  Nessun servizio Zoom trovato"
    }

    # ===================================================================
    # STEP 11: CLEANUP TEMPORANEO E FILE REMEDIATION
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 11: Pulizia file temporanei remediation..."

    # Rimuovi CleanZoom
    if (Test-Path $cleanZoomPath) {
        Remove-Item -Path $cleanZoomPath -Force -ErrorAction SilentlyContinue
        Write-Log "  Rimosso: CleanZoom.exe"
    }

    if (Test-Path $cleanZoomZip) {
        Remove-Item -Path $cleanZoomZip -Force -ErrorAction SilentlyContinue
        Write-Log "  Rimosso: CleanZoom.zip"
    }

    # ===================================================================
    # STEP 12: VERIFICA POST-REMEDIATION
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 12: Verifica post-remediation..."

    $stillInstalled = $false
    $residualFiles = @()

    # Check file residui
    $checkPaths = @(
        "$env:ProgramFiles\Zoom\bin\Zoom.exe",
        "${env:ProgramFiles(x86)}\Zoom\bin\Zoom.exe"
    )

    foreach ($checkPath in $checkPaths) {
        if (Test-Path $checkPath) {
            $stillInstalled = $true
            $residualFiles += $checkPath
            Write-Log "  WARNING: File ancora presente: $checkPath"
        }
    }

    # Check processi
    $runningZoom = Get-Process -Name "Zoom*" -ErrorAction SilentlyContinue
    if ($runningZoom) {
        Write-Log "  WARNING: Processi Zoom ancora in esecuzione: $($runningZoom.Count)"
        foreach ($proc in $runningZoom) {
            Write-Log "    - $($proc.Name) (PID: $($proc.Id))"
        }
        $stillInstalled = $true
    } else {
        Write-Log "  OK - Nessun processo Zoom in esecuzione"
    }

    # Check registry
    $regCheck = Get-ItemProperty "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*" -ErrorAction SilentlyContinue | 
        Where-Object { $_.DisplayName -like "*Zoom*" }

    if ($regCheck) {
        Write-Log "  WARNING: Entry registry ancora presenti: $($regCheck.Count)"
        $stillInstalled = $true
    } else {
        Write-Log "  OK - Nessuna entry Zoom in registry HKLM"
    }

    # ===================================================================
    # STEP 13: GENERAZIONE REPORT
    # ===================================================================
    Write-Log ""
    Write-Log "==================================================================="
    Write-Log "=== REPORT FINALE REMEDIATION ==================================="
    Write-Log "==================================================================="
    Write-Log ""
    Write-Log "STATISTICHE:"
    Write-Log "  - Processi terminati: $processesTerminated"
    Write-Log "  - Disinstallazioni riuscite: $uninstallCount"
    Write-Log "  - Disinstallazioni fallite: $failedUninstalls"
    Write-Log "  - Cartelle rimosse: $foldersRemoved"
    Write-Log "  - Cartelle con errori: $foldersSkipped"
    Write-Log "  - Chiavi registry rimosse: $regKeysRemoved"

