 ## 📝 Remediation Script Ottimizzato

```powershell
<#
.SYNOPSIS
    Remediation Script - Rimozione Completa Zoom Client
.DESCRIPTION
    Rimuove tutte le installazioni Zoom (system-wide e per-user) in modalità silent
    Utilizza uninstaller nativi e pulizia manuale
.NOTES
    Esecuzione: System Context
    Architettura: 64-bit only
    Richiede riavvio: No
    Metodo: Uninstaller nativo + CleanZoom + Pulizia manuale
    Versione: 1.1 - Ottimizzato
#>

# Verifica architettura - Exit se non 64-bit
if ([Environment]::Is64BitOperatingSystem -eq $false) {
    Write-Output "Sistema 32-bit - remediation non applicabile"
    Exit 0
}

try {
    $ErrorActionPreference = "Stop"

    # Percorso log
    $logPath = "$env:ProgramData\ZoomRemovalRemediation"
    if (!(Test-Path $logPath)) { 
        New-Item -ItemType Directory -Path $logPath -Force | Out-Null 
    }

    # Log unico con rotazione (fix: evita accumulo file)
    $remediationLog = "$logPath\Remediation.log"

    # Rotazione log se > 10MB
    if (Test-Path $remediationLog) {
        $logSize = (Get-Item $remediationLog).Length / 1MB
        if ($logSize -gt 10) {
            $archivePath = "$logPath\Archive"
            if (!(Test-Path $archivePath)) { 
                New-Item -ItemType Directory -Path $archivePath -Force | Out-Null 
            }
            $archiveName = "Remediation_$(Get-Date -Format 'yyyyMMdd_HHmmss').log"
            Move-Item $remediationLog "$archivePath\$archiveName" -Force -ErrorAction SilentlyContinue
        }
    }

    # Pulizia log vecchi (>30 giorni)
    if (Test-Path "$logPath\Archive") {
        Get-ChildItem "$logPath\Archive" -Filter "*.log" | 
            Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-30) } | 
            Remove-Item -Force -ErrorAction SilentlyContinue
    }

    function Write-Log {
        param($Message)
        $logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - $Message"
        $logMessage | Out-File $remediationLog -Append -Encoding UTF8
    }

    Write-Log "==================================================================="
    Write-Log "=== INIZIO REMEDIATION - RIMOZIONE ZOOM COMPLETA ================"
    Write-Log "==================================================================="
    Write-Log "Computer: $env:COMPUTERNAME"
    Write-Log "Sistema: 64-bit"
    Write-Log "User Context: SYSTEM"

    $uninstallCount = 0
    $failedUninstalls = 0
    $cleanupErrors = @()

    # ===================================================================
    # STEP 1: TERMINAZIONE PROCESSI ZOOM
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 1: Terminazione processi Zoom..."

    $zoomProcessNames = @(
        "Zoom", "ZoomWebinarHost", "ZoomNotes", "Outlook_Zoom_Plugin", 
        "zTscoder", "airhost", "aomhost64", "CptHost", "CptInstall", 
        "CptService", "RoomConnector", "ZComMsgr", "zCrashReport"
    )

    $processesTerminated = 0
    $processesRunning = 0

    foreach ($processName in $zoomProcessNames) {
        $processes = Get-Process -Name $processName -ErrorAction SilentlyContinue
        if ($processes) {
            $processesRunning += $processes.Count
            foreach ($proc in $processes) {
                try {
                    Write-Log "  Terminazione: $processName (PID: $($proc.Id))"
                    Stop-Process -Id $proc.Id -Force -ErrorAction Stop
                    $processesTerminated++
                    Write-Log "    OK - Processo terminato"
                } catch {
                    Write-Log "    WARNING: Impossibile terminare $processName (PID: $($proc.Id)): $_"
                    $cleanupErrors += "Processo $processName (PID: $($proc.Id))"
                }
            }
        }
    }

    if ($processesRunning -eq 0) {
        Write-Log "  Nessun processo Zoom in esecuzione"
    } else {
        Write-Log "  Processi terminati: $processesTerminated/$processesRunning"
    }

    # Attendi che i processi si chiudano completamente
    Start-Sleep -Seconds 3

    # Verifica che siano effettivamente chiusi
    $stillRunning = Get-Process -Name "Zoom*" -ErrorAction SilentlyContinue
    if ($stillRunning) {
        Write-Log "  WARNING: $($stillRunning.Count) processi Zoom ancora attivi dopo terminazione"
        foreach ($proc in $stillRunning) {
            Write-Log "    - $($proc.Name) (PID: $($proc.Id))"
        }
    }

    # ===================================================================
    # STEP 2: DOWNLOAD CleanZoom (Official Zoom Uninstaller)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 2: Download CleanZoom utility..."

    $cleanZoomPath = "$logPath\CleanZoom.exe"
    $cleanZoomUrl = "https://assets.zoom.us/docs/msi-templates/CleanZoom.zip"
    $cleanZoomZip = "$logPath\CleanZoom.zip"
    $cleanZoomAvailable = $false

    try {
        # Download CleanZoom
        Write-Log "  Download da: $cleanZoomUrl"
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

        # Timeout di 30 secondi per il download
        $webClient = New-Object System.Net.WebClient
        $webClient.DownloadFile($cleanZoomUrl, $cleanZoomZip)
        Write-Log "  Download completato: CleanZoom.zip ($(((Get-Item $cleanZoomZip).Length / 1KB).ToString('0.00')) KB)"

        # Estrai CleanZoom.exe
        Expand-Archive -Path $cleanZoomZip -DestinationPath $logPath -Force -ErrorAction Stop
        Write-Log "  Estratto: CleanZoom.exe"

        # Verifica che l'eseguibile esista
        if (Test-Path $cleanZoomPath) {
            $cleanZoomAvailable = $true
            Write-Log "  CleanZoom pronto per l'uso"
        }

        # Cleanup zip
        Remove-Item $cleanZoomZip -Force -ErrorAction SilentlyContinue

    } catch {
        Write-Log "  WARNING: Download/estrazione CleanZoom fallito: $_"
        Write-Log "  Procederò con metodo alternativo (uninstaller nativi)"
    }

    # ===================================================================
    # STEP 3: UNINSTALL SYSTEM-WIDE (HKLM)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 3: Disinstallazione system-wide (HKLM)..."

    $hklmPaths = @(
        "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )

    $systemAppsFound = 0

    foreach ($regPath in $hklmPaths) {
        $apps = Get-ItemProperty $regPath -ErrorAction SilentlyContinue | 
            Where-Object { 
                ($_.DisplayName -like "*Zoom*") -and 
                (($_.Publisher -like "*Zoom*") -or [string]::IsNullOrEmpty($_.Publisher))
            }

        foreach ($app in $apps) {
            $systemAppsFound++
            Write-Log "  Trovato: $($app.DisplayName) - Ver: $($app.DisplayVersion)"
            Write-Log "    Path: $($app.InstallLocation)"

            $uninstallString = $app.UninstallString
            $quietUninstallString = $app.QuietUninstallString

            # Prova prima QuietUninstallString se disponibile
            if ($quietUninstallString) {
                Write-Log "    Metodo: QuietUninstallString"
                Write-Log "    Comando: $quietUninstallString"

                try {
                    $process = Start-Process -FilePath "cmd.exe" -ArgumentList "/c `"$quietUninstallString`"" -Wait -NoNewWindow -PassThru -ErrorAction Stop

                    if ($process.ExitCode -eq 0) {
                        Write-Log "    OK - Disinstallazione completata (ExitCode: 0)"
                        $uninstallCount++
                    } else {
                        Write-Log "    WARNING - ExitCode: $($process.ExitCode)"
                        $failedUninstalls++
                    }
                } catch {
                    Write-Log "    ERRORE: $_"
                    $failedUninstalls++
                    $cleanupErrors += "System: $($app.DisplayName)"
                }
            } 
            elseif ($uninstallString) {
                # Costruisci comando silent
                if ($uninstallString -match "msiexec") {
                    # MSI installation
                    $silentUninstall = $uninstallString -replace "/I", "/X"
                    if ($silentUninstall -notmatch "/quiet") {
                        $silentUninstall += " /quiet /norestart"
                    }
                } else {
                    # EXE installation - aggiungi /silent se non presente
                    $silentUninstall = $uninstallString
                    if ($silentUninstall -notmatch "/silent") {
                        $silentUninstall += " /silent"
                    }
                }

                Write-Log "    Metodo: UninstallString (modificato)"
                Write-Log "    Comando: $silentUninstall"

                try {
                    $process = Start-Process -FilePath "cmd.exe" -ArgumentList "/c `"$silentUninstall`"" -Wait -NoNewWindow -PassThru -ErrorAction Stop

                    if ($process.ExitCode -eq 0) {
                        Write-Log "    OK - Disinstallazione completata (ExitCode: 0)"
                        $uninstallCount++
                    } else {
                        Write-Log "    WARNING - ExitCode: $($process.ExitCode)"
                        # Alcuni uninstaller usano exit code diversi da 0 per successo
                        if ($process.ExitCode -eq 3010) {
                            Write-Log "    (Riavvio richiesto - considerato successo)"
                            $uninstallCount++
                        } else {
                            $failedUninstalls++
                        }
                    }
                } catch {
                    Write-Log "    ERRORE: $_"
                    $failedUninstalls++
                    $cleanupErrors += "System: $($app.DisplayName)"
                }
            } else {
                Write-Log "    WARNING: Nessun UninstallString disponibile"
                $failedUninstalls++
            }

            # Attendi completamento
            Start-Sleep -Seconds 2
        }
    }

    if ($systemAppsFound -eq 0) {
        Write-Log "  Nessuna installazione system-wide trovata in registry"
    }

    # ===================================================================
    # STEP 4: UNINSTALL PER-USER (HKEY_USERS)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 4: Disinstallazione per-user..."

    # Ottieni tutti i profili utente
    $userProfiles = Get-ChildItem "C:\Users" -Directory -ErrorAction SilentlyContinue | 
        Where-Object { $_.Name -notmatch '^(Public|Default|All Users|Default User|TEMP)$' }

    Write-Log "  Profili utente da scansionare: $($userProfiles.Count)"

    $userAppsFound = 0

    foreach ($profile in $userProfiles) {
        Write-Log "  Controllo profilo: $($profile.Name)"

        # FIX: Gestione robusta traduzione SID (stesso fix del detection)
        $sid = $null

        try {
            # Tentativo 1: Nome semplice (utenti locali)
            $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
        } catch {
            # Tentativo 2: COMPUTERNAME\username
            try {
                $sid = (New-Object System.Security.Principal.NTAccount("$env:COMPUTERNAME\$($profile.Name)")).Translate([System.Security.Principal.SecurityIdentifier]).Value
            } catch {
                # Tentativo 3: Cerca SID da ProfileList registry
                try {
                    $profileListPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\*"
                    $profileReg = Get-ItemProperty $profileListPath -ErrorAction SilentlyContinue | 
                        Where-Object { $_.ProfileImagePath -eq $profile.FullName }

                    if ($profileReg) {
                        $sid = $profileReg.PSChildName
                    }
                } catch {
                    Write-Log "    WARNING: Impossibile ottenere SID - Skip (Azure AD o profilo orfano)"
                    continue
                }
            }
        }

        if (!$sid) {
            Write-Log "    Skip - SID non ottenibile"
            continue
        }

        Write-Log "    SID: $sid"

        # Trova uninstaller in AppData
        $userUninstallerPaths = @(
            "$($profile.FullName)\AppData\Roaming\Zoom\uninstall\Installer.exe",
            "$($profile.FullName)\AppData\Local\Zoom\uninstall\Installer.exe"
        )

        foreach ($uninstallerPath in $userUninstallerPaths) {
            if (Test-Path $uninstallerPath) {
                $userAppsFound++
                Write-Log "    Trovato uninstaller: $uninstallerPath"

                try {
                    # Esegui uninstaller Zoom per-user
                    $process = Start-Process -FilePath $uninstallerPath -ArgumentList "/uninstall /silent" -Wait -NoNewWindow -PassThru -ErrorAction Stop

                    if ($process.ExitCode -eq 0) {
                        Write-Log "    OK - Disinstallazione completata"
                        $uninstallCount++
                    } else {
                        Write-Log "    WARNING - ExitCode: $($process.ExitCode)"
                        # Considera comunque successo se ExitCode < 100
                        if ($process.ExitCode -lt 100) {
                            $uninstallCount++
                        } else {
                            $failedUninstalls++
                        }
                    }
                } catch {
                    Write-Log "    ERRORE: $_"
                    $failedUninstalls++
                    $cleanupErrors += "User ($($profile.Name)): uninstaller"
                }

                Start-Sleep -Seconds 2
            }
        }

        # Verifica anche registry per-user
        $userRegPath = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"

        try {
            $userApps = Get-ItemProperty $userRegPath -ErrorAction SilentlyContinue | 
                Where-Object { $_.DisplayName -like "*Zoom*" }

            if ($userApps) {
                foreach ($userApp in $userApps) {
                    Write-Log "    Registry entry: $($userApp.DisplayName)"
                    # Uninstall già tentato sopra tramite Installer.exe
                }
            }
        } catch {
            Write-Log "    WARNING: Errore lettura registry user: $_"
        }
    }

    if ($userAppsFound -eq 0) {
        Write-Log "  Nessuna installazione per-user trovata"
    }

    # ===================================================================
    # STEP 5: ESECUZIONE CleanZoom (se disponibile)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 5: Esecuzione CleanZoom utility..."

    if ($cleanZoomAvailable -and (Test-Path $cleanZoomPath)) {
        try {
            Write-Log "  Esecuzione: CleanZoom.exe /silent"
            $process = Start-Process -FilePath $cleanZoomPath -ArgumentList "/silent" -Wait -NoNewWindow -PassThru -ErrorAction Stop

            Write-Log "  CleanZoom completato - ExitCode: $($process.ExitCode)"
            $uninstallCount++
        } catch {
            Write-Log "  WARNING: CleanZoom fallito: $_"
        }
    } else {
        Write-Log "  CleanZoom non disponibile - skip"
    }

    # ===================================================================
    # STEP 6: PULIZIA MANUALE FILE E CARTELLE RESIDUE
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 6: Pulizia file e cartelle residue..."

    $foldersRemoved = 0
    $foldersSkipped = 0

    # Cartelle system-wide
    $systemFolders = @(
        "$env:ProgramFiles\Zoom",
        "${env:ProgramFiles(x86)}\Zoom",
        "$env:ProgramData\Zoom",
        "$env:ProgramData\ZoomInstaller"  # Aggiungi cartella installer
    )

    foreach ($folder in $systemFolders) {
        if (Test-Path $folder) {
            Write-Log "  Tentativo rimozione: $folder"
            try {
                # Prima prova rimozione ricorsiva
                Remove-Item -Path $folder -Recurse -Force -ErrorAction Stop
                Write-Log "    OK - Cartella rimossa"
                $foldersRemoved++
            } catch {
                Write-Log "    WARNING: $_"

                # Tentativo alternativo: forza unlock dei file
                try {
                    Get-ChildItem -Path $folder -Recurse -Force | 
                        ForEach-Object { 
                            $_.Attributes = 'Normal'
                            Remove-Item $_.FullName -Force -ErrorAction SilentlyContinue 
                        }
                    Remove-Item -Path $folder -Recurse -Force -ErrorAction Stop
                    Write-Log "    OK - Cartella rimossa (secondo tentativo)"
                    $foldersRemoved++
                } catch {
                    Write-Log "    ERRORE: Impossibile rimuovere completamente"
                    $foldersSkipped++
                    $cleanupErrors += "Folder: $folder"
                }
            }
        }
    }

    # Cartelle per-user
    foreach ($profile in $userProfiles) {
        $userZoomFolders = @(
            "$($profile.FullName)\AppData\Roaming\Zoom",
            "$($profile.FullName)\AppData\Local\Zoom",
            "$($profile.FullName)\Documents\Zoom"
        )

        foreach ($userFolder in $userZoomFolders) {
            if (Test-Path $userFolder) {
                Write-Log "  Tentativo rimozione (User: $($profile.Name)): $userFolder"
                try {
                    Remove-Item -Path $userFolder -Recurse -Force -ErrorAction Stop
                    Write-Log "    OK - Cartella rimossa"
                    $foldersRemoved++
                } catch {
                    Write-Log "    WARNING: $_"
                    $foldersSkipped++
                    $cleanupErrors += "User folder ($($profile.Name)): $userFolder"
                }
            }
        }
    }

    Write-Log "  Cartelle rimosse: $foldersRemoved"
    if ($foldersSkipped -gt 0) {
        Write-Log "  Cartelle con errori: $foldersSkipped"
    }

    # ===================================================================
    # STEP 7: PULIZIA REGISTRY RESIDUO
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 7: Pulizia registry residuo..."

    $regKeysRemoved = 0
    $regKeysSkipped = 0

    # Registry system-wide
    $registryPaths = @(
        "HKLM:\Software\Zoom",
        "HKLM:\Software\WOW6432Node\Zoom",
        "HKLM:\Software\Classes\ZoomLauncher",
        "HKLM:\Software\Classes\.zoom",
        "HKLM:\Software\Classes\zoom"
    )

    foreach ($regPath in $registryPaths) {
        if (Test-Path $regPath) {
            Write-Log "  Tentativo rimozione: $regPath"
            try {
                Remove-Item -Path $regPath -Recurse -Force -ErrorAction Stop
                Write-Log "    OK - Chiave rimossa"
                $regKeysRemoved++
            } catch {
                Write-Log "    WARNING: $_"
                $regKeysSkipped++
                $cleanupErrors += "Registry: $regPath"
            }
        }
    }

    # Registry per-user
    foreach ($profile in $userProfiles) {
        # Ottieni SID (usa stessa logica robusta)
        $sid = $null
        try {
            $sid = (New-Object System.Security.Principal.NTAccount($profile.Name)).Translate([System.Security.Principal.SecurityIdentifier]).Value
        } catch {
            try {
                $sid = (New-Object System.Security.Principal.NTAccount("$env:COMPUTERNAME\$($profile.Name)")).Translate([System.Security.Principal.SecurityIdentifier]).Value
            } catch {
                continue  # Skip se SID non ottenibile
            }
        }

        if ($sid) {
            $userRegPaths = @(
                "Registry::HKEY_USERS\$sid\Software\Zoom",
                "Registry::HKEY_USERS\$sid\Software\Classes\ZoomLauncher"
            )

            foreach ($userRegPath in $userRegPaths) {
                if (Test-Path $userRegPath) {
                    Write-Log "  Tentativo rimozione (User: $($profile.Name)): $userRegPath"
                    try {
                        Remove-Item -Path $userRegPath -Recurse -Force -ErrorAction Stop
                        Write-Log "    OK - Chiave user rimossa"
                        $regKeysRemoved++
                    } catch {
                        Write-Log "    WARNING: $_"
                        $regKeysSkipped++
                    }
                }
            }
        }
    }

    Write-Log "  Chiavi registry rimosse: $regKeysRemoved"
    if ($regKeysSkipped -gt 0) {
        Write-Log "  Chiavi con errori: $regKeysSkipped"
    }

    # ===================================================================
    # STEP 8: RIMOZIONE SHORTCUTS
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 8: Rimozione collegamenti..."

    $shortcutsRemoved = 0

    $shortcutLocations = @(
        "$env:ProgramData\Microsoft\Windows\Start Menu\Programs",
        "$env:Public\Desktop"
    )

    foreach ($profile in $userProfiles) {
        $shortcutLocations += "$($profile.FullName)\AppData\Roaming\Microsoft\Windows\Start Menu\Programs"
        $shortcutLocations += "$($profile.FullName)\Desktop"
    }

    foreach ($location in $shortcutLocations) {
        if (Test-Path $location) {
            $shortcuts = Get-ChildItem -Path $location -Recurse -Filter "*Zoom*.lnk" -ErrorAction SilentlyContinue
            foreach ($shortcut in $shortcuts) {
                Write-Log "  Tentativo rimozione: $($shortcut.FullName)"
                try {
                    Remove-Item -Path $shortcut.FullName -Force -ErrorAction Stop
                    Write-Log "    OK - Collegamento rimosso"
                    $shortcutsRemoved++
                } catch {
                    Write-Log "    WARNING: $_"
                }
            }
        }
    }

    if ($shortcutsRemoved -eq 0) {
        Write-Log "  Nessun collegamento trovato"
    } else {
        Write-Log "  Collegamenti rimossi: $shortcutsRemoved"
    }

    # ===================================================================
    # STEP 9: PULIZIA TASK SCHEDULER
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 9: Pulizia Scheduled Tasks..."

    $tasksRemoved = 0

    $zoomTasks = Get-ScheduledTask -ErrorAction SilentlyContinue | 
        Where-Object { $_.TaskName -like "*Zoom*" }

    if ($zoomTasks) {
        foreach ($task in $zoomTasks) {
            Write-Log "  Tentativo rimozione: $($task.TaskName) (Path: $($task.TaskPath))"
            try {
                Unregister-ScheduledTask -TaskName $task.TaskName -TaskPath $task.TaskPath -Confirm:$false -ErrorAction Stop
                Write-Log "    OK - Task rimosso"
                $tasksRemoved++
            } catch {
                Write-Log "    WARNING: $_"
            }
        }
    } else {
        Write-Log "  Nessun Scheduled Task Zoom trovato"
    }

    # ===================================================================
    # STEP 10: PULIZIA SERVIZI (se esistenti)
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 10: Pulizia servizi Zoom..."

    $servicesRemoved = 0
    $zoomServices = Get-Service -Name "*Zoom*" -ErrorAction SilentlyContinue

    if ($zoomServices) {
        foreach ($service in $zoomServices) {
            Write-Log "  Trovato servizio: $($service.Name) - Status: $($service.Status)"
            try {
                # Stop servizio se running
                if ($service.Status -eq 'Running') {
                    Stop-Service -Name $service.Name -Force -ErrorAction Stop
                    Write-Log "    Servizio arrestato"
                }

                # Rimuovi servizio
                sc.exe delete $service.Name | Out-Null
                Write-Log "    OK - Servizio rimosso"
                $servicesRemoved++
            } catch {
                Write-Log "    WARNING: $_"
            }
        }
    } else {
        Write-Log "  Nessun servizio Zoom trovato"
    }

    # ===================================================================
    # STEP 11: CLEANUP TEMPORANEO E FILE REMEDIATION
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 11: Pulizia file temporanei remediation..."

    # Rimuovi CleanZoom
    if (Test-Path $cleanZoomPath) {
        Remove-Item -Path $cleanZoomPath -Force -ErrorAction SilentlyContinue
        Write-Log "  Rimosso: CleanZoom.exe"
    }

    if (Test-Path $cleanZoomZip) {
        Remove-Item -Path $cleanZoomZip -Force -ErrorAction SilentlyContinue
        Write-Log "  Rimosso: CleanZoom.zip"
    }

    # ===================================================================
    # STEP 12: VERIFICA POST-REMEDIATION
    # ===================================================================
    Write-Log ""
    Write-Log "STEP 12: Verifica post-remediation..."

    $stillInstalled = $false
    $residualFiles = @()

    # Check file residui
    $checkPaths = @(
        "$env:ProgramFiles\Zoom\bin\Zoom.exe",
        "${env:ProgramFiles(x86)}\Zoom\bin\Zoom.exe"
    )

    foreach ($checkPath in $checkPaths) {
        if (Test-Path $checkPath) {
            $stillInstalled = $true
            $residualFiles += $checkPath
            Write-Log "  WARNING: File ancora presente: $checkPath"
        }
    }

    # Check processi
    $runningZoom = Get-Process -Name "Zoom*" -ErrorAction SilentlyContinue
    if ($runningZoom) {
        Write-Log "  WARNING: Processi Zoom ancora in esecuzione: $($runningZoom.Count)"
        foreach ($proc in $runningZoom) {
            Write-Log "    - $($proc.Name) (PID: $($proc.Id))"
        }
        $stillInstalled = $true
    } else {
        Write-Log "  OK - Nessun processo Zoom in esecuzione"
    }

    # Check registry
    $regCheck = Get-ItemProperty "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*" -ErrorAction SilentlyContinue | 
        Where-Object { $_.DisplayName -like "*Zoom*" }

    if ($regCheck) {
        Write-Log "  WARNING: Entry registry ancora presenti: $($regCheck.Count)"
        $stillInstalled = $true
    } else {
        Write-Log "  OK - Nessuna entry Zoom in registry HKLM"
    }

    # ===================================================================
    # STEP 13: GENERAZIONE REPORT
    # ===================================================================
    Write-Log ""
    Write-Log "==================================================================="
    Write-Log "=== REPORT FINALE REMEDIATION ==================================="
    Write-Log "==================================================================="
    Write-Log ""
    Write-Log "STATISTICHE:"
    Write-Log "  - Processi terminati: $processesTerminated"
    Write-Log "  - Disinstallazioni riuscite: $uninstallCount"
    Write-Log "  - Disinstallazioni fallite: $failedUninstalls"
    Write-Log "  - Cartelle rimosse: $foldersRemoved"
    Write-Log "  - Cartelle con errori: $foldersSkipped"
    Write-Log "  - Chiavi registry rimosse: $regKeysRemoved"
